using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back.")]
    public static string Echo([Description("The message to echo")] string message) => $"Echo: {message}";

    [McpServerTool(Name = "add"), Description("Adds two numbers together.")]
    public static double Add(
        [Description("First number")] double a,
        [Description("Second number")] double b) => a + b;
}

using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-settings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            MaxConnections = 100,
            Features = new[] { "tools", "resources" }
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/status", Name = "app-status",
        Title = "Application Status", MimeType = "application/json")]
    public static string GetAppStatus()
    {
        var status = new
        {
            Status = "healthy",
            Uptime = Environment.TickCount64 / 1000,
            Timestamp = DateTimeOffset.UtcNow
        };
        return JsonSerializer.Serialize(status, new JsonSerializerOptions { WriteIndented = true });
    }
}

